1→//! Read-only access to one projected identity session.
//!
//! `GET /api/identity/sled?session_id=...` retains the existing route while
//! resolving a session-scoped `identity_sled` record. Omitting the selector is
//! accepted only when the projection contains exactly one current session.

use axum::{
    body::Body,
    extract::{Extension, Query},
10→    http::{HeaderMap, StatusCode, header},
    response::{IntoResponse, Response},
};
use serde::Deserialize;
use serde_json::json;
use std::sync::Arc;
use base64::Engine as _;
use op_grpc_bridge::GhostbridgeCallMetadata;
use tracing::{info, warn};

20→use crate::state::AppState;

/// Parse the single authenticated credential accepted by the generic door.
pub(crate) fn ghostbridge_metadata(
    headers: &HeaderMap,
) -> Result<GhostbridgeCallMetadata, Response> {
    let decode = |name| {
        decode_identity_header(headers, name)
            .map_err(|message| identity_error(StatusCode::BAD_REQUEST, message))
    };
30→    let sid = decode(op_identity::sealed_id::HTTP_HEADER_NAME)?;
    let oia = decode("x-oracle-identity-assertion-bin")?;
    if sid.is_some() == oia.is_some() {
        return Err(identity_error(
            StatusCode::UNAUTHORIZED,
            "send exactly one identity credential",
        ));
    }
    Ok(GhostbridgeCallMetadata {
        sealed_id: sid,
40→        oracle_assertion: oia,
        session_genesis: None,
        trace_id: None,
        wireguard_pubkey: None,
    })
}

/// Require the human SID1 credential for private UI workspace operations.
pub(crate) fn sid1_metadata(headers: &HeaderMap) -> Result<GhostbridgeCallMetadata, Response> {
    let sid = decode_identity_header(headers, op_identity::sealed_id::HTTP_HEADER_NAME)
50→        .map_err(|message| identity_error(StatusCode::BAD_REQUEST, message))?
        .ok_or_else(|| identity_error(StatusCode::UNAUTHORIZED, "SID1 identity is required"))?;
    let oracle = decode_identity_header(headers, "x-oracle-identity-assertion-bin")
        .map_err(|message| identity_error(StatusCode::BAD_REQUEST, message))?;
    if oracle.is_some() || !sid.starts_with(b"SID1") {
        return Err(identity_error(
            StatusCode::UNAUTHORIZED,
            "private UI workspace requires exactly one SID1 identity",
        ));
    }
60→    Ok(GhostbridgeCallMetadata {
        sealed_id: Some(sid),
        oracle_assertion: None,
        session_genesis: None,
        trace_id: None,
        wireguard_pubkey: None,
    })
}

fn decode_identity_header(
70→    headers: &HeaderMap,
    name: &'static str,
) -> Result<Option<Vec<u8>>, &'static str> {
    let values: Vec<_> = headers.get_all(name).iter().collect();
    if values.is_empty() {
        return Ok(None);
    }
    if values.len() != 1 {
        return Err("identity header must occur once");
    }
80→    let encoded = values[0]
        .to_str()
        .map_err(|_| "identity header is not valid ASCII")?;
    if encoded.len() > (16_usize * 1024 * 4).div_ceil(3) {
        return Err("identity credential is too large");
    }
    let wire = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .decode(encoded)
        .map_err(|_| "identity header is not canonical base64url")?;
    if wire.is_empty()
90→        || wire.len() > 16 * 1024
        || base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(&wire) != encoded
    {
        return Err("identity header is not canonical base64url");
    }
    Ok(Some(wire))
}

fn identity_error(status: StatusCode, message: &str) -> Response {
    (status, axum::Json(json!({"error": message}))).into_response()
100→}

#[derive(Debug, Default, Deserialize)]
pub struct IdentityQuery {
    pub session_id: Option<String>,
}

/// Return a single active, unexpired identity record from the shared projection.
pub async fn identity_sled_handler(
    Extension(_state): Extension<Arc<AppState>>,
110→    Query(query): Query<IdentityQuery>,
) -> Response {
    match op_identity::resolve_identity_session(query.session_id.as_deref()) {
        Ok(identity) => {
            let genesis = identity.genesis.clone().unwrap_or_default();
            let schema_catalog_hash = op_identity::schema_bridge::schema_catalog_hash()
                .map(hex::encode)
                .unwrap_or_else(|| "(missing)".to_string());
            let projection_path = op_core::projection_shm::projection_file_path("identity_sled");

120→            let body = json!({
                "path": projection_path,
                "is_valid": identity.is_current(),
                "session_id": identity.session_id,
                "wireguard_pubkey": identity.wireguard_pubkey,
                "mutation_index": identity.mutation_index,
                "genesis": genesis,
                "trace_id": identity.trace_id,
                "schema_version": identity.schema_version,
                "schema_catalog_hash": schema_catalog_hash,
130→                "backend": false,
            });

            info!("Served projected identity session");
            Response::builder()
                .status(StatusCode::OK)
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::to_vec(&body).expect("identity body serialization should not fail"),
                ))
140→                .expect("response with valid body should not fail")
        }
        Err(error) => {
            warn!(%error, "Identity session not available");
            Response::builder()
                .status(StatusCode::SERVICE_UNAVAILABLE)
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    json!({
                        "error": "Identity session not available",
150→                        "detail": error.to_string(),
                    })
                    .to_string(),
                ))
                .expect("response with valid body should not fail")
        }
    }
}
