1→//! Chat API Handlers — sealed-door adapters for human chat ingress.
//!
//! Blocking HTTP submit is exactly `chat_response.start_conversation` (when
//! needed) then `chat_response.submit_turn`, then `get_turn_response` until the
//! designated responder commits. No loopback `:8084` or local `chat_manager` generation.
//! Streaming belongs to
//! `op_chat.chat.ChatService.Send` on the gRPC door.

use axum::{
10→    extract::{Extension, Path},
    http::{HeaderMap, StatusCode},
    response::{
        IntoResponse, Json, Response,
        sse::{Event, Sse},
    },
};
use base64::Engine;
use futures::stream::Stream;
use op_grpc_bridge::GhostbridgeCallMetadata;
20→use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{OwnedValue as Value, json};
use std::convert::Infallible;
use std::sync::Arc;
use std::time::Duration;
use tracing::{error, info};

use crate::state::{AppState, call_sealed_method};

30→const CHAT_RESPONSE_PLUGIN: &str = "chat_response";
const SUBMIT_CAPABILITY: &str = "chat_response.submit";
const READ_CAPABILITY: &str = "chat_response.read";
/// Match bridge turn TTL (`chat_response_turns::TURN_TTL_SECONDS`).
const RESPONSE_WAIT: Duration = Duration::from_secs(300);
const RESPONSE_POLL: Duration = Duration::from_millis(250);

#[derive(Debug, Deserialize)]
pub struct ChatRequest {
    pub message: String,
40→    #[serde(default)]
    pub session_id: Option<String>,
    /// Accepted for compatibility; overrides are rejected (authoritative selection).
    #[serde(default)]
    pub model: Option<String>,
    /// Accepted for compatibility; overrides are rejected.
    #[serde(default)]
    pub provider: Option<String>,
    #[serde(default)]
    pub user_id: Option<String>,
50→    #[serde(default)]
    pub container_id: Option<String>,
}

#[derive(Debug, Deserialize)]
pub struct CreateSessionRequest {
    #[serde(default)]
    pub title: Option<String>,
}

60→#[derive(Debug, Serialize)]
pub struct ChatResponse {
    pub success: bool,
    pub message: String,
    // Frontend-compatible aliases (openclaw/ChatPage.tsx expects these)
    pub content: String,
    pub role: String,
    pub id: String,
    pub tool_name: Option<String>,
    pub error: Option<String>,
70→    pub tools_executed: Vec<String>,
    pub session_id: String,
    pub model: String,
    pub provider: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub container_id: Option<String>,
}

fn chat_failure(
    session_id: String,
80→    container_id: Option<String>,
    error: impl Into<String>,
) -> Json<ChatResponse> {
    let error = error.into();
    Json(ChatResponse {
        success: false,
        message: String::new(),
        content: error.clone(),
        role: "assistant".to_string(),
        id: format!("msg-{}", uuid::Uuid::new_v4()),
90→        tool_name: None,
        error: Some(error),
        tools_executed: vec![],
        session_id,
        model: String::new(),
        provider: CHAT_RESPONSE_PLUGIN.to_string(),
        container_id,
    })
}

100→/// Build door CallMethod identity metadata for this handler.
fn chat_identity(headers: &HeaderMap) -> Result<GhostbridgeCallMetadata, String> {
    let decode = |name: &'static str| -> Result<Option<Vec<u8>>, String> {
        let values: Vec<_> = headers.get_all(name).iter().collect();
        if values.is_empty() {
            return Ok(None);
        }
        if values.len() != 1 {
            return Err("identity header must occur once".into());
        }
110→        let encoded = values[0]
            .to_str()
            .map_err(|_| "identity header is not valid ASCII")?;
        if encoded.len() > (16_usize * 1024 * 4).div_ceil(3) {
            return Err("identity credential is too large".into());
        }
        base64::engine::general_purpose::URL_SAFE_NO_PAD
            .decode(encoded)
            .map(Some)
            .map_err(|_| "identity credential is not valid base64url".into())
120→    };
    let sid = decode(op_identity::sealed_id::HTTP_HEADER_NAME)?;
    let oia = decode("x-oracle-identity-assertion-bin")?;
    if sid.is_some() == oia.is_some() {
        return Err("send exactly one identity credential".into());
    }
    Ok(GhostbridgeCallMetadata {
        sealed_id: sid,
        oracle_assertion: oia,
        session_genesis: None,
130→        trace_id: None,
        wireguard_pubkey: None,
    })
}

fn message_from_committed_turn(turn: &serde_json::Value) -> Option<(String, String, Vec<String>)> {
    let response_id = turn
        .get("response_id")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
140→        .to_string();
    let content = turn.get("content")?;
    let kind = content.get("kind").and_then(|v| v.as_str())?;
    let (text, actions) = match kind {
        "user_response" => (
            content.get("message")?.as_str()?.to_string(),
            content
                .get("related_actions")
                .and_then(|v| v.as_array())
                .map(|items| {
150→                    items
                        .iter()
                        .filter_map(|item| item.as_str().map(str::to_string))
                        .collect()
                })
                .unwrap_or_default(),
        ),
        "clarification" => (content.get("question")?.as_str()?.to_string(), vec![]),
        "refusal" => (content.get("reason")?.as_str()?.to_string(), vec![]),
        _ => return None,
160→    };
    Some((response_id, text, actions))
}

async fn ensure_conversation(
    identity: &GhostbridgeCallMetadata,
    session_id: Option<&str>,
) -> anyhow::Result<String> {
    if let Some(id) = session_id.map(str::trim).filter(|id| !id.is_empty()) {
        // Bridge contracts require a UUID conversation id (same as ChatService).
170→        uuid::Uuid::parse_str(id).map_err(|_| anyhow::anyhow!("invalid conversation_id"))?;
        return Ok(id.to_string());
    }
    let started = call_sealed_method(
        CHAT_RESPONSE_PLUGIN,
        "start_conversation",
        serde_json::json!({}),
        READ_CAPABILITY,
        identity,
    )
180→    .await?;
    started
        .get("conversation_id")
        .and_then(|v| v.as_str())
        .map(str::to_string)
        .ok_or_else(|| anyhow::anyhow!("start_conversation returned no conversation_id"))
}

async fn submit_and_await_committed(
    identity: &GhostbridgeCallMetadata,
190→    conversation_id: &str,
    message: &str,
) -> anyhow::Result<(String, String, Vec<String>)> {
    let submitted = call_sealed_method(
        CHAT_RESPONSE_PLUGIN,
        "submit_turn",
        serde_json::json!({
            "conversation_id": conversation_id,
            "message": message,
            "response_mode": "text",
200→        }),
        SUBMIT_CAPABILITY,
        identity,
    )
    .await?;
    let turn_id = submitted
        .get("turn_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("submit_turn returned no turn_id"))?
        .to_string();
210→    let deadline = tokio::time::Instant::now() + RESPONSE_WAIT;
    loop {
        let response = call_sealed_method(
            CHAT_RESPONSE_PLUGIN,
            "get_turn_response",
            serde_json::json!({ "turn_id": turn_id }),
            READ_CAPABILITY,
            identity,
        )
        .await?;
220→        if let Some(turn) = response.get("turn").filter(|t| !t.is_null()) {
            return message_from_committed_turn(turn)
                .ok_or_else(|| anyhow::anyhow!("committed turn has no readable response content"));
        }
        if tokio::time::Instant::now() >= deadline {
            anyhow::bail!("response wait expired; generation or commit outcome is unknown");
        }
        tokio::time::sleep(RESPONSE_POLL).await;
    }
}
230→
/// POST /api/chat/message (and any route that reuses this handler) — human
/// submit through the sealed door into `chat_response` turns.
pub async fn chat_handler(
    headers: HeaderMap,
    Extension(state): Extension<Arc<AppState>>,
    Json(request): Json<ChatRequest>,
) -> Json<ChatResponse> {
    info!(
        "Chat door submit: {} chars, user: {:?}",
240→        request.message.len(),
        request.user_id
    );

    let placeholder_session = request
        .session_id
        .clone()
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    if request
250→        .provider
        .as_deref()
        .is_some_and(|value| !value.is_empty())
        || request.model.as_deref().is_some_and(|value| !value.is_empty())
    {
        return chat_failure(
            placeholder_session,
            request.container_id.clone(),
            "chat uses the authoritative selection; model overrides are not accepted",
        );
260→    }

    let message = request.message.trim();
    if message.is_empty() || message.len() > 1024 * 1024 {
        return chat_failure(
            placeholder_session,
            request.container_id.clone(),
            "expected one nonempty bounded user message",
        );
    }
270→
    let identity = match chat_identity(&headers) {
        Ok(identity) => identity,
        Err(error) => {
            return chat_failure(placeholder_session, request.container_id.clone(), error);
        }
    };

    let conversation_id = match ensure_conversation(&identity, request.session_id.as_deref()).await
    {
280→        Ok(id) => id,
        Err(error) => {
            return chat_failure(
                placeholder_session,
                request.container_id.clone(),
                error.to_string(),
            );
        }
    };

290→    let _ = state
        .conversations
        .create_session(conversation_id.clone(), None)
        .await;

    let container_id = if let Some(cid) = state
        .conversations
        .get_container_id(&conversation_id)
        .await
    {
300→        Some(cid)
    } else if let Some(cid) = request.container_id.clone() {
        let _ = state
            .conversations
            .set_container_id(&conversation_id, cid.clone())
            .await;
        Some(cid)
    } else if let Some(user_id) = request.user_id.clone() {
        let cid = state
            .user_store
310→            .get_user(&user_id)
            .await
            .and_then(|u| u.privacy_container_name);
        if let Some(ref c) = cid {
            let _ = state
                .conversations
                .set_container_id(&conversation_id, c.clone())
                .await;
        }
        cid
320→    } else {
        None
    };

    let _ = state
        .conversations
        .append_message(
            &conversation_id,
            op_llm::ChatMessage::user(message.to_string()),
        )
330→        .await;

    match submit_and_await_committed(&identity, &conversation_id, message).await {
        Ok((response_id, response_message, tools_executed)) => {
            let _ = state
                .conversations
                .append_message(
                    &conversation_id,
                    op_llm::ChatMessage::assistant(response_message.clone()),
                )
340→                .await;
            Json(ChatResponse {
                success: true,
                message: response_message.clone(),
                content: response_message,
                role: "assistant".to_string(),
                id: if response_id.is_empty() {
                    format!("msg-{}", uuid::Uuid::new_v4())
                } else {
                    response_id
350→                },
                tool_name: None,
                error: None,
                tools_executed,
                session_id: conversation_id,
                model: String::new(),
                provider: CHAT_RESPONSE_PLUGIN.to_string(),
                container_id,
            })
        }
360→        Err(error) => chat_failure(conversation_id, container_id, error.to_string()),
    }
}

/// POST /api/chat/stream — refuse local SSE generation; streaming is ChatService.
pub async fn chat_stream_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Json(_request): Json<ChatRequest>,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    let stream = async_stream::stream! {
370→        let payload = json!({
            "error": "use op_chat.chat.ChatService.Send on the gRPC bridge door for streaming; HTTP submit uses /api/chat/message → chat_response.submit_turn",
            "success": false,
        });
        yield Ok(Event::default().data(simd_json::to_string(&payload).unwrap_or_default()));
    };

    Sse::new(stream).keep_alive(
        axum::response::sse::KeepAlive::new()
            .interval(Duration::from_secs(15))
380→            .text("ping"),
    )
}

/// GET /api/chat/history/:session_id - Get conversation history
pub async fn get_history_handler(
    Extension(state): Extension<Arc<AppState>>,
    Path(session_id): Path<String>,
) -> Json<Value> {
    if let Some(history) = state.conversations.get_history(&session_id).await {
390→        Json(json!({
            "session_id": session_id,
            "messages": history.iter().map(|m| json!({
                "role": m.role,
                "content": m.content
            })).collect::<Vec<_>>()
        }))
    } else {
        Json(json!({
            "session_id": session_id,
400→            "messages": []
        }))
    }
}

/// GET /api/chat/sessions - List all chat sessions
pub async fn list_sessions_handler(Extension(state): Extension<Arc<AppState>>) -> Json<Value> {
    let sessions: Vec<Value> = state
        .conversations
        .list_sessions()
410→        .await
        .into_iter()
        .map(|(id, msg_count, title)| {
            json!({
                "id": id,
                "title": title,
                "date": chrono::Utc::now().to_rfc3339(),
                "messages": msg_count
            })
        })
420→        .collect();

    Json(json!({ "sessions": sessions }))
}

/// POST /api/chat/sessions - Create a new chat session
pub async fn create_session_handler(
    Extension(state): Extension<Arc<AppState>>,
    Json(payload): Json<CreateSessionRequest>,
) -> (StatusCode, Json<Value>) {
430→    let session_id = uuid::Uuid::new_v4().to_string();
    let title = payload.title.unwrap_or_else(|| "New Chat".to_string());

    if let Err(err) = state
        .conversations
        .create_session(session_id.clone(), Some(title.clone()))
        .await
    {
        error!(%err, "Failed to create chat session");
        return (
440→            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": "Failed to persist chat session"})),
        );
    }

