fn valid_transcript_filename(filename: &str) -> bool {
    !filename.is_empty()
        && filename.len() <= 128
        && filename != "."
        && filename != ".."
770→        && filename
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
}

