                            ChatMessage {
                                role: "system".to_string(),
                                content: core_prompt.clone(),
                                tool_calls: None,
                                tool_call_id: None,
                            },
                            ChatMessage::user(input),
                        ];
                        let fallback_request = ChatRequest {
