pub fn sse_plugin_allowlist() -> Vec<String> {
40→    match std::env::var("OP_WEB_SSE_PLUGINS") {
        Ok(raw) if !raw.trim().is_empty() => raw
            .split(',')
            .map(str::trim)
            .filter(|id| !id.is_empty())
            .map(str::to_string)
